import React from 'react';
import { Link } from 'react-router-dom';
import { motion } from 'framer-motion';
import { FiBookOpen, FiUsers, FiAward, FiMonitor, FiShield, FiSmartphone } from 'react-icons/fi';
import { PageTransition, Button, Card } from '../components/ui';

// Animation variants
const containerVariant = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: {
      staggerChildren: 0.1,
      delayChildren: 0.2
    }
  }
};

const itemVariant = {
  hidden: { opacity: 0, y: 20 },
  visible: {
    opacity: 1,
    y: 0,
    transition: { 
      duration: 0.5,
      ease: [0.4, 0, 0.2, 1]
    }
  }
};

const Home = () => {
  const features = [
    {
      title: 'دروس فيديو تفاعلية',
      description: 'شاهد دروسًا مصورة بجودة عالية وتعلم المفاهيم بطريقة مبسطة وممتعة',
      icon: <FiMonitor className="h-8 w-8 text-primary" />
    },
    {
      title: 'اختبارات وتمارين',
      description: 'قم بإجراء اختبارات تفاعلية تساعدك على التحقق من فهمك للمواد الدراسية',
      icon: <FiAward className="h-8 w-8 text-accent" />
    },
    {
      title: 'منتدى للمناقشة',
      description: 'تفاعل مع المعلمين والطلاب الآخرين واستفسر عن أي مسألة تواجهك',
      icon: <FiUsers className="h-8 w-8 text-primary" />
    },
    {
      title: 'شهادات إتمام',
      description: 'احصل على شهادات معتمدة لتوثيق مهاراتك وإنجازاتك التعليمية',
      icon: <FiBookOpen className="h-8 w-8 text-accent" />
    },
    {
      title: 'متوافقة مع جميع الأجهزة',
      description: 'استعمل المنصة من أي جهاز محمول أو مكتبي بسهولة تامة',
      icon: <FiSmartphone className="h-8 w-8 text-primary" />
    },
    {
      title: 'تتبع التقدم',
      description: 'راقب تقدمك في التعلم مع خيارات متابعة تفصيلية ورسوم بيانية',
      icon: <FiShield className="h-8 w-8 text-accent" />
    }
  ];

  const howItWorksSteps = [
    {
      number: 1,
      title: 'أنشئ حسابك',
      description: 'سجل حساب أو قم بتسجيل الدخول بسهولة'
    },
    {
      number: 2,
      title: 'اختر الدروس',
      description: 'تصفح قائمة الدروس واختر ما يناسب احتياجاتك التعليمية'
    },
    {
      number: 3,
      title: 'ابدأ التعلم',
      description: 'شاهد الدروس وحل التمارين وتفاعل مع المعلمين والطلاب'
    }
  ];

  return (
    <PageTransition>
      {/* Hero Section */}
      <section className="relative overflow-hidden bg-gradient-to-br from-primary to-primary-700 text-white py-16 md:py-24">
        <div className="absolute inset-0 bg-[url('/img/pattern.svg')] opacity-10"></div>
        
        <div className="container mx-auto px-4 relative z-10">
          <motion.div 
            className="text-center max-w-4xl mx-auto"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6 }}
          >
            <h1 className="text-4xl md:text-5xl lg:text-6xl font-bold mb-6">
              تعلم بطريقة مبتكرة
            </h1>
            <p className="text-xl md:text-2xl mb-10 text-white/90">
              منصة تعليمية عربية متكاملة تجمع بين المعلمين والطلاب في بيئة تفاعلية سهلة الاستخدام
            </p>
            
            <div className="flex flex-col sm:flex-row gap-4 justify-center">
              <Button 
                variant="accent" 
                size="lg" 
                className="shadow-lg"
                as={Link}
                to="/register/student"
              >
                ابدأ التعلم الآن
              </Button>
              <Button 
                variant="outline" 
                size="lg"
                className="bg-white/10 border-white text-white hover:bg-white/20 dark:bg-white/5"
                as={Link}
                to="/about"
              >
                تعرف على المزيد
              </Button>
            </div>
          </motion.div>
          
          <motion.div
            className="mt-16"
            initial={{ opacity: 0, y: 40 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.7, delay: 0.3 }}
          >
            <div className="relative h-64 md:h-96 rounded-xl overflow-hidden shadow-2xl">
              <div className="absolute inset-0 bg-gradient-to-t from-primary-800/80 to-transparent z-10"></div>
              <img 
                src="/img/hero-image.jpg" 
                alt="طلاب يتعلمون" 
                className="w-full h-full object-cover"
              />
            </div>
          </motion.div>
        </div>
        
        <div className="absolute bottom-0 left-0 right-0 h-16 bg-gradient-to-t from-background-light dark:from-gray-900 to-transparent"></div>
      </section>

      {/* Features Section */}
      <section className="py-20 bg-background-light dark:bg-gray-900">
        <div className="container mx-auto px-4">
          <motion.div 
            className="text-center max-w-3xl mx-auto mb-16"
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.5 }}
          >
            <h2 className="text-3xl md:text-4xl font-bold mb-4">ما يميز منصتنا التعليمية</h2>
            <p className="text-text-secondary dark:text-gray-400 text-lg">المميزات التي تجعل منصتنا تحقق أفضل النتائج التعليمية</p>
          </motion.div>
          
          <motion.div
            className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8"
            variants={containerVariant}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true }}
          >
            {features.map((feature, index) => (
              <motion.div 
                key={index} 
                variants={itemVariant}
                whileHover={{ y: -8, transition: { duration: 0.3 } }}
              >
                <Card className="h-full p-8 border-t-4 border-t-primary dark:border-t-primary-600 hover:shadow-xl transition-all duration-300">
                  <div className="flex flex-col h-full">
                    <div className="bg-primary-50 dark:bg-gray-800 p-4 rounded-full w-16 h-16 flex items-center justify-center mb-6">
                      {feature.icon}
                    </div>
                    <h3 className="text-xl font-bold mb-3">{feature.title}</h3>
                    <p className="text-text-secondary dark:text-gray-400 flex-grow">{feature.description}</p>
                  </div>
                </Card>
              </motion.div>
            ))}
          </motion.div>
        </div>
      </section>

      {/* How It Works Section */}
      <section className="py-20 bg-gray-50 dark:bg-gray-800">
        <div className="container mx-auto px-4">
          <motion.div 
            className="text-center max-w-3xl mx-auto mb-16"
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.5 }}
          >
            <h2 className="text-3xl md:text-4xl font-bold mb-4">كيف تعمل المنصة؟</h2>
            <p className="text-text-secondary dark:text-gray-400 text-lg">ثلاث خطوات بسيطة تبدأ بها رحلتك التعليمية</p>
          </motion.div>
          
          <div className="flex flex-col md:flex-row justify-between items-center gap-8 relative">
            {/* Connecting line */}
            <div className="absolute top-1/2 left-0 right-0 h-1 bg-primary/20 hidden md:block"></div>
            
            {howItWorksSteps.map((step, index) => (
              <motion.div 
                key={index}
                className="w-full md:w-1/3 relative z-10"
                initial={{ opacity: 0, y: 30 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true }}
                transition={{ duration: 0.5, delay: index * 0.2 }}
              >
                <div className="bg-white dark:bg-gray-700 rounded-2xl p-8 text-center shadow-lg h-full flex flex-col items-center">
                  <div className="w-16 h-16 rounded-full bg-primary text-white flex items-center justify-center text-2xl font-bold mb-6">
                    {step.number}
                  </div>
                  <h3 className="text-xl font-bold mb-3">{step.title}</h3>
                  <p className="text-text-secondary dark:text-gray-300">{step.description}</p>
                </div>
              </motion.div>
            ))}
          </div>
        </div>
      </section>

      {/* CTA Section */}
      <section className="py-20 bg-gradient-to-br from-accent-500 to-accent-700 text-white">
        <div className="container mx-auto px-4">
          <motion.div 
            className="text-center max-w-3xl mx-auto"
            initial={{ opacity: 0, scale: 0.95 }}
            whileInView={{ opacity: 1, scale: 1 }}
            viewport={{ once: true }}
            transition={{ duration: 0.5 }}
          >
            <h2 className="text-3xl md:text-4xl font-bold mb-6">جاهز للبدء في رحلتك التعليمية؟</h2>
            <p className="text-white/90 text-xl mb-10">انضم إلى منصتنا التعليمية اليوم واستمتع بطريقة تفاعلية مبتكرة</p>
            <Button 
              variant="primary" 
              size="lg" 
              className="bg-white text-accent-600 hover:bg-gray-100 shadow-xl"
              as={Link}
              to="/register/student"
            >
              سجل الآن
            </Button>
          </motion.div>
        </div>
      </section>
    </PageTransition>
  );
};

export default Home;
